import json

grid = [
    [0, 5, 0, 0, 0, 0, 0, 5, 0, 0, 5, 0],
    [0, 5, 0, 0, 0, 5, 5, 5, 0, 5, 5, 0],
    [5, 5, 5, 0, 0, 5, 0, 5, 5, 5, 0, 0],
    [0, 0, 5, 5, 5, 5, 0, 5, 0, 5, 5, 0],
    [0, 0, 0, 5, 0, 0, 0, 5, 0, 0, 5, 0]
]

rows, cols = len(grid), len(grid[0])

# Find deep interior 0s (all 4 neighbors are 0)
# Also 0s next to these should become 8, forming a propagation

output = [row[:] for row in grid]

# Check each 0: if any neighbor is 5, it stays 0; only 0s surrounded by 0s become 8
for r in range(rows):
    for c in range(cols):
        if grid[r][c] == 0:
            # Check if this 0 is adjacent to any 5
            neighbors = []
            if r > 0 and grid[r-1][c] == 5: neighbors.append((r-1, c))
            if r < rows-1 and grid[r+1][c] == 5: neighbors.append((r+1, c))
            if c > 0 and grid[r][c-1] == 5: neighbors.append((r, c-1))
            if c < cols-1 and grid[r][c+1] == 5: neighbors.append((r, c+1))

            # Are there any 5 neighbors?
            if len(neighbors) == 0:
                # No 5 neighbors - this 0 is "deep interior"
                output[r][c] = 8
            # Else: stays 0

print("Transformed grid:")
for row in output:
    print(row)

print("\nOutput as JSON:")
print(json.dumps(output))

import json

grid = [
    [0, 5, 0, 0, 0, 0, 0, 5, 0, 0, 5, 0],
    [0, 5, 0, 0, 0, 5, 5, 5, 0, 5, 5, 0],
    [5, 5, 5, 0, 0, 5, 0, 5, 5, 5, 0, 0],
    [0, 0, 5, 5, 5, 5, 0, 5, 0, 5, 5, 0],
    [0, 0, 0, 5, 0, 0, 0, 5, 0, 0, 5, 0]
]

rows, cols = len(grid), len(grid[0])

# Rule: 0s with no 5 to their left (wall side) become 7
# 0s with 5 to their left (interior side) become 8
output = [row[:] for row in grid]

for r in range(rows):
    for c in range(cols):
        if grid[r][c] == 0:
            # Check if there's a 5 to the left
            has_5_left = False
            for cc in range(c):
                if grid[r][cc] == 5:
                    has_5_left = True
                    break

            if has_5_left:
                output[r][c] = 8
            else:
                output[r][c] = 7

print("Result (left wall = 7, interior = 8):")
for row in output:
    print(row)
print(json.dumps(output))

import json

grid = [
    [0, 5, 0, 0, 0, 0, 0, 5, 0, 0, 5, 0],
    [0, 5, 0, 0, 0, 5, 5, 5, 0, 5, 5, 0],
    [5, 5, 5, 0, 0, 5, 0, 5, 5, 5, 0, 0],
    [0, 0, 5, 5, 5, 5, 0, 5, 0, 5, 5, 0],
    [0, 0, 0, 5, 0, 0, 0, 5, 0, 0, 5, 0]
]

rows, cols = 5, 12

output = [row[:] for row in grid]

for r in range(rows):
    for c in range(cols):
        if grid[r][c] == 0:
            # Check 4-directional neighbors for 5
            has_5_neighbor = False
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) == (r, c):
                    continue
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 5:
                    has_5_neighbor = True
                    break
            if has_5_neighbor:
                output[r][c] = 8

print("Result (5-neighbors become 8):")
for row in output:
    print(row)
print(json.dumps(output))

