import numpy as np

grid = np.array([
    [0, 5, 0, 0, 0, 0, 0, 5, 0, 0, 5, 0],
    [0, 5, 0, 0, 0, 5, 5, 5, 0, 5, 5, 0],
    [5, 5, 5, 0, 0, 5, 0, 5, 5, 5, 0, 0],
    [0, 0, 5, 5, 5, 5, 0, 5, 0, 5, 5, 0],
    [0, 0, 0, 5, 0, 0, 0, 5, 0, 0, 5, 0]
])

# Check for regular patterns - maybe count consecutive 5s
print("Horizontal runs of 5s per row:")
for i, row in enumerate(grid):
    runs = []
    current = 0
    for j, val in enumerate(row):
        if val == 5:
            current += 1
        else:
            if current > 0:
                runs.append(current)
                current = 0
    if current > 0:
        runs.append(current)
    print(f"Row {i}: {runs}")

print("\nVertical runs of 5s per column:")
for j in range(grid.shape[1]):
    runs = []
    current = 0
    for i in range(grid.shape[0]):
        if grid[i, j] == 5:
            current += 1
        else:
            if current > 0:
                runs.append(current)
                current = 0
    if current > 0:
        runs.append(current)
    print(f"Col {j}: {runs}")

